mapper.select:
SELECT w.warehouse_name AS warehouseName, cat.category_name AS categoryName, sku.sku_code AS goodsCode, COALESCE(spu.goods_name, sku.sku_name) AS goodsName, sku.spec_info AS spec, sku.unit_name AS unit, -- 期初：按统计区间开始日期前的最新库存流水计算 COALESCE(begin_qty.qty, 0) AS beginQty, -- 期初金额：按统计区间开始日期前的最新库存流水成本估算 COALESCE(begin_amt.amt, 0) AS beginAmount, -- 期间入库 COALESCE(in_qty.qty, 0) AS inQty, COALESCE(in_amt.amt, 0) AS inAmount, -- 期间出库 COALESCE(out_qty.qty, 0) AS outQty, COALESCE(out_amt.amt, 0) AS outAmount, -- 期末：按统计区间结束日期前的最新库存流水计算 COALESCE(end_qty.qty, 0) AS endQty, COALESCE(end_amt.amt, 0) AS endAmount FROM wms_warehouse w CROSS JOIN wms_goods_sku sku LEFT JOIN wms_goods spu ON sku.goods_id = spu.id AND spu.del_flag = '0' LEFT JOIN wms_goods_category cat ON spu.category_id = cat.id AND cat.del_flag = '0' -- 期初库存（统计区间开始日期之前） LEFT JOIN (
SELECT warehouse_id, sku_id, after_qty AS qty FROM ( SELECT warehouse_id, sku_id, after_qty, ROW_NUMBER() OVER ( PARTITION BY warehouse_id, sku_id ORDER BY create_time DESC, id DESC ) AS rn FROM wms_stock_log WHERE del_flag = '0' AND DATE(create_time) < #{startDate} ) t WHERE rn = 1
SELECT st.warehouse_id, st.sku_id, st.quantity AS qty FROM wms_stock st
) begin_qty ON w.id = begin_qty.warehouse_id AND sku.id = begin_qty.sku_id LEFT JOIN (
SELECT warehouse_id, sku_id, after_qty * COALESCE(cost_price, 0) AS amt FROM ( SELECT warehouse_id, sku_id, after_qty, cost_price, ROW_NUMBER() OVER ( PARTITION BY warehouse_id, sku_id ORDER BY create_time DESC, id DESC ) AS rn FROM wms_stock_log WHERE del_flag = '0' AND DATE(create_time) < #{startDate} ) t WHERE rn = 1
SELECT st.warehouse_id, st.sku_id, st.quantity * COALESCE(s.cost_price, 0) AS amt FROM wms_stock st INNER JOIN wms_goods_sku s ON st.sku_id = s.id
) begin_amt ON w.id = begin_amt.warehouse_id AND sku.id = begin_amt.sku_id -- 期间入库数量 LEFT JOIN ( SELECT pi.warehouse_id, pii.sku_id, SUM(pii.quantity) AS qty FROM wms_purchase_in_item pii INNER JOIN wms_purchase_in pi ON pii.in_id = pi.id WHERE pi.del_flag = '0' AND pi.status = '1'
AND DATE(pi.create_time) BETWEEN #{startDate} AND #{endDate}
AND DATE(pi.create_time) >= DATE_SUB(CURDATE(), INTERVAL 30 DAY)
GROUP BY pi.warehouse_id, pii.sku_id ) in_qty ON w.id = in_qty.warehouse_id AND sku.id = in_qty.sku_id -- 期间入库金额 LEFT JOIN ( SELECT pi.warehouse_id, pii.sku_id, SUM(pii.amount) AS amt FROM wms_purchase_in_item pii INNER JOIN wms_purchase_in pi ON pii.in_id = pi.id WHERE pi.del_flag = '0' AND pi.status = '1'
AND DATE(pi.create_time) BETWEEN #{startDate} AND #{endDate}
AND DATE(pi.create_time) >= DATE_SUB(CURDATE(), INTERVAL 30 DAY)
GROUP BY pi.warehouse_id, pii.sku_id ) in_amt ON w.id = in_amt.warehouse_id AND sku.id = in_amt.sku_id -- 期间出库数量 LEFT JOIN ( SELECT so.warehouse_id, soi.sku_id, SUM(soi.quantity) AS qty FROM wms_sales_out_item soi INNER JOIN wms_sales_out so ON soi.out_id = so.id WHERE so.del_flag = '0' AND so.status = '1'
AND DATE(so.create_time) BETWEEN #{startDate} AND #{endDate}
AND DATE(so.create_time) >= DATE_SUB(CURDATE(), INTERVAL 30 DAY)
GROUP BY so.warehouse_id, soi.sku_id ) out_qty ON w.id = out_qty.warehouse_id AND sku.id = out_qty.sku_id -- 期间出库金额 LEFT JOIN ( SELECT so.warehouse_id, soi.sku_id, SUM(soi.amount) AS amt FROM wms_sales_out_item soi INNER JOIN wms_sales_out so ON soi.out_id = so.id WHERE so.del_flag = '0' AND so.status = '1'
AND DATE(so.create_time) BETWEEN #{startDate} AND #{endDate}
AND DATE(so.create_time) >= DATE_SUB(CURDATE(), INTERVAL 30 DAY)
GROUP BY so.warehouse_id, soi.sku_id ) out_amt ON w.id = out_amt.warehouse_id AND sku.id = out_amt.sku_id -- 期末库存（统计区间结束日期之前） LEFT JOIN (
SELECT warehouse_id, sku_id, after_qty AS qty FROM ( SELECT warehouse_id, sku_id, after_qty, ROW_NUMBER() OVER ( PARTITION BY warehouse_id, sku_id ORDER BY create_time DESC, id DESC ) AS rn FROM wms_stock_log WHERE del_flag = '0' AND DATE(create_time) <= #{endDate} ) t WHERE rn = 1
SELECT st.warehouse_id, st.sku_id, st.quantity AS qty FROM wms_stock st
) end_qty ON w.id = end_qty.warehouse_id AND sku.id = end_qty.sku_id LEFT JOIN (
SELECT warehouse_id, sku_id, after_qty * COALESCE(cost_price, 0) AS amt FROM ( SELECT warehouse_id, sku_id, after_qty, cost_price, ROW_NUMBER() OVER ( PARTITION BY warehouse_id, sku_id ORDER BY create_time DESC, id DESC ) AS rn FROM wms_stock_log WHERE del_flag = '0' AND DATE(create_time) <= #{endDate} ) t WHERE rn = 1
SELECT st.warehouse_id, st.sku_id, st.quantity * COALESCE(s.cost_price, 0) AS amt FROM wms_stock st INNER JOIN wms_goods_sku s ON st.sku_id = s.id
) end_amt ON w.id = end_amt.warehouse_id AND sku.id = end_amt.sku_id WHERE w.del_flag = '0' AND sku.del_flag = '0'
AND spu.category_id IN
#{id}
AND w.id IN
#{id}
AND (COALESCE(spu.goods_name, sku.sku_name) LIKE CONCAT('%', #{goodsName}, '%') OR sku.sku_code LIKE CONCAT('%', #{goodsName}, '%'))
-- 只显示有数据的商品：有库存或有进出的 AND (COALESCE(begin_qty.qty, 0) > 0 OR COALESCE(end_qty.qty, 0) > 0 OR COALESCE(in_qty.qty, 0) > 0 OR COALESCE(out_qty.qty, 0) > 0) ORDER BY w.warehouse_name, sku.sku_code
